import Testing

@testable import WSurf

// A passkey as Apple Passwords sends it. CXF 3.3.12 fixes the key as PKCS#8 DER and the user handle as the relying party's
// user.id, which WebAuthn asks to keep to 64 bytes or fewer and which real relying parties (PayPal) make longer; WSurf keeps up
// to `WebsitePasskey.userHandleLimit`. Every key here is generated by the test, in the shapes real encoders write.
extension CredentialExchangeTests {
    private func derElement(_ tag: UInt8, _ contents: Data) -> Data {
        let count = contents.count
        var length = Data([UInt8(count & 0xFF)])
        if count >= 256 {
            length = Data([0x82, UInt8(count >> 8), UInt8(count & 0xFF)])
        } else if count >= 128 {
            length = Data([0x81, UInt8(count)])
        }
        return Data([tag]) + length + contents
    }

    private static let ecPublicKeyOID = Data([0x2A, 0x86, 0x48, 0xCE, 0x3D, 0x02, 0x01])
    private static let p256OID = Data([0x2A, 0x86, 0x48, 0xCE, 0x3D, 0x03, 0x01, 0x07])

    /// A PKCS#8 P-256 key built field by field, so a test can write what one encoder writes and another does not.
    private func pkcs8(
        scalar: Data,
        publicKey: Data? = nil,
        curveInside: Bool = false,
        version: UInt8 = 0,
        trailing: [(tag: UInt8, contents: Data)] = []
    ) -> Data {
        var inner = derElement(0x02, Data([1])) + derElement(0x04, scalar)
        if curveInside {
            inner += derElement(0xA0, derElement(0x06, Self.p256OID))
        }
        if let publicKey {
            inner += derElement(0xA1, derElement(0x03, Data([0]) + publicKey))
        }
        let algorithm = derElement(0x06, Self.ecPublicKeyOID) + derElement(0x06, Self.p256OID)
        var body = derElement(0x02, Data([version])) + derElement(0x30, algorithm) + derElement(0x04, derElement(0x30, inner))
        for (tag, contents) in trailing {
            body += derElement(tag, contents)
        }
        return derElement(0x30, body)
    }

    private func ed25519PKCS8() -> Data {
        Data([0x30, 0x2E, 0x02, 0x01, 0x00, 0x30, 0x05, 0x06, 0x03, 0x2B, 0x65, 0x70, 0x04, 0x22, 0x04, 0x20]) + Data(repeating: 7, count: 32)
    }

    private func applePasskey(
        credentialID: Data = Data((0..<32).map { UInt8($0 &* 7 &+ 3) }),
        rpID: String = "paypal.com",
        userName: String = "ada@example.test",
        userHandle: Data = Data((0..<64).map { UInt8(255 - $0) }),
        key: Data,
        extensions: Any? = nil
    ) -> ASImportableCredential {
        var value = ASImportableCredential.Passkey(
            credentialID: credentialID,
            relyingPartyIdentifier: rpID,
            userName: userName,
            userDisplayName: "Ada Lovelace",
            userHandle: userHandle,
            key: key
        )
        if #available(macOS 26.4, *) {
            value.fido2Extensions = extensions as? ASImportableFIDO2Extensions
        }
        return .passkey(value)
    }

    private func previewOfPasskey(_ credential: ASImportableCredential) throws -> CredentialImportPreview {
        try CredentialExchangeCodec.preview(
            data(credentials: [basicAuthentication(username: "ada", password: "pw"), credential]),
            against: snapshot([])
        )
    }

    // MARK: What Apple Passwords sends is imported

    @Test func aPasskeyAsApplePasswordsSendsItIsImported() throws {
        for rpID in ["paypal.com", "www.paypal.com"] {
            let key = P256.Signing.PrivateKey()
            var extensions: Any?
            if #available(macOS 26.4, *) {
                extensions = ASImportableFIDO2Extensions(
                    hmacCredentials: .init(algorithm: .sha256, credentialWithUV: Data(repeating: 1, count: 32), credentialWithoutUV: Data(repeating: 2, count: 32)),
                    largeBlob: .init(uncompressedSize: 129, data: Data(repeating: 3, count: 96))
                )
            }
            let longestHandle = Data((0..<WebsitePasskey.userHandleLimit).map { UInt8(truncatingIfNeeded: 255 - $0) })
            let preview = try previewOfPasskey(applePasskey(rpID: rpID, userHandle: longestHandle, key: key.derRepresentation, extensions: extensions))

            #expect(preview.omitted.isEmpty, "\(rpID)")
            let stored = try #require(preview.candidates.first?.passkeys.first, "\(rpID)")
            #expect(stored.rpID == rpID && stored.userHandle == longestHandle && stored.exchangeFIDO2Metadata != nil, "\(rpID)")
            let signer = try PasskeyKeyEncoding.importPKCS8(stored.privateKeyPKCS8)
            let message = Data("assertion".utf8)
            #expect(try key.publicKey.isValidSignature(signer.signature(for: message), for: message), "\(rpID)")
        }
    }

    @Test func theKeyInTheCXFDocumentExampleIsReadable() throws {
        // The passkey example of the CXF document (section 3.3.12), base64url, as the standard prints it.
        let example = "MIGHAgEAMBMGByqGSM49AgEGCCqGSM49AwEHBG0wawIBAQQgARu_0sCt20EpgVxb4Puq3Ga5VVLpuTY75ngvZlyq3X6h"
            + "RANCAASmdk1xLsK0oOlhxIPp0d1ZuS0sT9nf6BZtSelhqvLBW0fOL33l_bXgsr_STUHjCLn8l6gcRJwe7OQvbQubZ1dY"
        var base64 = example.replacingOccurrences(of: "-", with: "+").replacingOccurrences(of: "_", with: "/")
        base64 += String(repeating: "=", count: (4 - base64.count % 4) % 4)
        let der = try #require(Data(base64Encoded: base64))

        let preview = try previewOfPasskey(applePasskey(key: der))

        #expect(preview.omitted.isEmpty && preview.candidates.first?.passkeys.count == 1)
    }

    @Test func everyRFCEncodingOfTheSameP256KeyIsImported() throws {
        let leadingZero = Data([0x00]) + Data(repeating: 0x11, count: 31)
        let key = P256.Signing.PrivateKey()
        let zeroKey = try P256.Signing.PrivateKey(rawRepresentation: leadingZero)
        let scalar = key.rawRepresentation
        let publicKey = key.publicKey.x963Representation
        let encodings: [(name: String, key: P256.Signing.PrivateKey, der: Data)] = [
            ("CryptoKit derRepresentation", key, key.derRepresentation),
            ("curve and public key inside", key, pkcs8(scalar: scalar, publicKey: publicKey, curveInside: true)),
            ("scalar only", key, pkcs8(scalar: scalar)),
            ("version 1 with the public key after the key", key, pkcs8(scalar: scalar, version: 1, trailing: [(0x81, Data([0]) + publicKey)])),
            ("attributes after the key", key, pkcs8(scalar: scalar, trailing: [(0xA0, Data())])),
            ("attributes then public key", key, pkcs8(scalar: scalar, version: 1, trailing: [(0xA0, Data()), (0x81, Data([0]) + publicKey)])),
            ("scalar with its leading zero byte dropped", zeroKey, pkcs8(scalar: leadingZero.dropFirst())),
        ]
        for encoding in encodings {
            let imported = try #require(try? PasskeyKeyEncoding.importPKCS8(encoding.der), "\(encoding.name)")
            #expect(imported.rawRepresentation == encoding.key.rawRepresentation, "\(encoding.name)")

            let preview = try previewOfPasskey(applePasskey(key: encoding.der))
            #expect(preview.omitted.isEmpty, "\(encoding.name)")
            let stored = try #require(preview.candidates.first?.passkeys.first, "\(encoding.name)")
            #expect(try PasskeyKeyEncoding.importPKCS8(stored.privateKeyPKCS8).rawRepresentation == encoding.key.rawRepresentation, "\(encoding.name)")
        }
    }

    @Test func keysThatAreNotAReadableP256KeyAreStillRefused() throws {
        let key = P256.Signing.PrivateKey()
        let scalar = key.rawRepresentation
        let publicKey = key.publicKey.x963Representation
        let refused: [(name: String, der: Data)] = [
            ("zero scalar", pkcs8(scalar: Data(repeating: 0, count: 32))),
            ("scalar over 32 bytes", pkcs8(scalar: Data([1]) + scalar)),
            ("empty scalar", pkcs8(scalar: Data())),
            ("version 2", pkcs8(scalar: scalar, version: 2)),
            ("unknown element after the key", pkcs8(scalar: scalar, trailing: [(0x05, Data())])),
            ("public key before attributes", pkcs8(scalar: scalar, version: 1, trailing: [(0x81, Data([0]) + publicKey), (0xA0, Data())])),
            ("attributes twice", pkcs8(scalar: scalar, trailing: [(0xA0, Data()), (0xA0, Data())])),
            ("public key of another key", pkcs8(scalar: scalar, publicKey: P256.Signing.PrivateKey().publicKey.x963Representation)),
            ("bare 32-byte scalar", scalar),
            ("X9.63 private key", key.x963Representation),
            ("SEC1 ECPrivateKey", derElement(0x30, derElement(0x02, Data([1])) + derElement(0x04, scalar) + derElement(0xA0, derElement(0x06, Self.p256OID)))),
            ("P-384", P384.Signing.PrivateKey().derRepresentation),
            ("RSA", try rsaPKCS8()),
            ("Ed25519", ed25519PKCS8()),
            ("empty", Data()),
        ]
        for entry in refused {
            #expect(throws: (any Error).self, "\(entry.name)") { try PasskeyKeyEncoding.importPKCS8(entry.der) }
        }

        #expect(PasskeyKeyEncoding.isAnotherAlgorithm(try rsaPKCS8()))
        #expect(PasskeyKeyEncoding.isAnotherAlgorithm(ed25519PKCS8()))
        #expect(PasskeyKeyEncoding.isAnotherAlgorithm(P384.Signing.PrivateKey().derRepresentation))
        for unreadable in [Data(), Data([0x30, 0x82, 0x01]), scalar, key.x963Representation, key.derRepresentation, pkcs8(scalar: scalar, version: 2)] {
            #expect(!PasskeyKeyEncoding.isAnotherAlgorithm(unreadable))
        }
    }

    // MARK: What is left out is named exactly

    private struct PasskeyCase {
        let name: String
        let credential: ASImportableCredential
        let reason: CredentialImportOmission.Reason
    }

    @Test func eachReasonAPasskeyIsLeftOutHasItsOwnTextAndNeverTheContent() throws {
        let secret = "must-not-appear-in-the-review"
        let key = P256.Signing.PrivateKey().derRepresentation
        func passkey(
            id: Data = Data([0xC0, 0x01]), rpID: String = "paypal.com", handle: Data = Data([0x31]), name: String = secret, key: Data = key
        ) -> ASImportableCredential {
            applePasskey(credentialID: id, rpID: rpID, userName: name, userHandle: handle, key: key)
        }
        var cases = [
            PasskeyCase(name: "RSA key", credential: passkey(key: try rsaPKCS8()), reason: .passkeyAlgorithmNotSupported),
            PasskeyCase(name: "P-384 key", credential: passkey(key: P384.Signing.PrivateKey().derRepresentation), reason: .passkeyAlgorithmNotSupported),
            PasskeyCase(name: "Ed25519 key", credential: passkey(key: ed25519PKCS8()), reason: .passkeyAlgorithmNotSupported),
            PasskeyCase(name: "truncated key", credential: passkey(key: Data(key.prefix(40))), reason: .passkeyKeyUnreadable),
            PasskeyCase(name: "raw scalar", credential: passkey(key: Data(secret.utf8.prefix(32))), reason: .passkeyKeyUnreadable),
            PasskeyCase(name: "no credential ID", credential: passkey(id: Data()), reason: .passkeyCredentialIDInvalid),
            PasskeyCase(
                name: "credential ID over the limit",
                credential: passkey(id: Data(repeating: 1, count: WebsitePasskey.credentialIDLimit + 1)), reason: .passkeyCredentialIDInvalid
            ),
            PasskeyCase(name: "no user handle", credential: passkey(handle: Data()), reason: .passkeyUserHandleMissing),
            PasskeyCase(
                name: "user handle over the limit",
                credential: passkey(handle: Data(repeating: 2, count: WebsitePasskey.userHandleLimit + 1)), reason: .passkeyUserHandleTooLong
            ),
            PasskeyCase(
                name: "user name over the limit",
                credential: passkey(name: String(repeating: "x", count: WebsitePasskey.nameLimit + 1)), reason: .passkeyNameTooLong
            ),
            PasskeyCase(name: "public suffix", credential: passkey(rpID: "com"), reason: .passkeyWebsiteNotAllowed),
            PasskeyCase(name: "private suffix", credential: passkey(rpID: "github.io"), reason: .passkeyWebsiteNotAllowed),
            PasskeyCase(name: "IP address", credential: passkey(rpID: "127.0.0.1"), reason: .passkeyWebsiteNotAllowed),
            PasskeyCase(name: "name with a port", credential: passkey(rpID: "paypal.com:443"), reason: .passkeyWebsiteNotAllowed),
            PasskeyCase(name: "no website", credential: passkey(rpID: ""), reason: .passkeyWebsiteNotAllowed),
        ]
        if #available(macOS 26.4, *) {
            // Under the 4 MB an item may hold, but over the 4 MB one stored field may hold once the extension data is encoded.
            let blob = ASImportableFIDO2Extensions(hmacCredentials: nil, largeBlob: .init(uncompressedSize: 1, data: Data(repeating: 0, count: 3_000_001)))
            cases.append(PasskeyCase(
                name: "extension data over the limit",
                credential: applePasskey(key: key, extensions: blob), reason: .passkeyExtensionsTooLarge
            ))
        }

        var texts: [String] = []
        for entry in cases {
            let preview = try previewOfPasskey(entry.credential)

            #expect(preview.candidates.first?.passkeys.isEmpty == true, "\(entry.name)")
            #expect(preview.omitted.map(\.reason) == [entry.reason], "\(entry.name)")
            #expect(preview.omitted.map(\.kind) == [.passkey], "\(entry.name)")
            #expect(preview.omitted.first?.record == .credential(account: 0, item: 0, credential: 1), "\(entry.name)")
            let text = try #require(preview.omitted.first?.text, "\(entry.name)")
            #expect(!text.contains("can’t be stored") && !text.contains(secret) && !String(describing: preview.omitted).contains(secret), "\(entry.name)")
            texts.append(text)
        }
        let distinctReasons = Set(cases.map { "\($0.reason)" })
        #expect(Set(texts).count == distinctReasons.count, "one text per reason")
        // The number is printed with the locale's grouping ("1,024"), so compare its digits.
        let handleText = try #require(zip(cases, texts).first { $0.0.reason == .passkeyUserHandleTooLong }?.1)
        #expect(handleText.filter(\.isNumber) == "\(WebsitePasskey.userHandleLimit)")
    }

    @Test func aPasskeyAtEveryLimitIsKept() throws {
        let key = P256.Signing.PrivateKey().derRepresentation
        let preview = try previewOfPasskey(applePasskey(
            credentialID: Data(repeating: 9, count: WebsitePasskey.credentialIDLimit),
            userName: String(repeating: "x", count: WebsitePasskey.nameLimit),
            userHandle: Data(repeating: 8, count: WebsitePasskey.userHandleLimit),
            key: key
        ))

        #expect(preview.omitted.isEmpty && preview.candidates.first?.passkeys.count == 1)
    }

    // MARK: A user handle longer than 64 bytes

    @Test func theUserHandleBoundIsOneThousandAndTwentyFourBytesAndNeverEmpty() throws {
        // The literal, so the bound cannot drift with the constant: the credential ID bound, not the 64 WebAuthn recommends.
        #expect(WebsitePasskey.userHandleLimit == 1_024 && WebsitePasskey.userHandleLimit == WebsitePasskey.credentialIDLimit)

        let key = P256.Signing.PrivateKey().derRepresentation
        for (length, kept) in [(1, true), (64, true), (65, true), (96, true), (512, true), (1_024, true), (1_025, false), (4_096, false)] {
            let preview = try previewOfPasskey(applePasskey(userHandle: Data(repeating: 0x5A, count: length), key: key))

            #expect(preview.candidates.first?.passkeys.count == (kept ? 1 : 0), "\(length) bytes")
            if kept {
                #expect(preview.omitted.isEmpty, "\(length) bytes")
            } else {
                #expect(preview.omitted.map(\.reason) == [.passkeyUserHandleTooLong], "\(length) bytes")
                // The text names the bound, printed with the locale's grouping ("1,024"), never the old 64.
                #expect(preview.omitted.first?.text.filter(\.isNumber) == "1024", "\(length) bytes")
            }
        }
        let empty = try previewOfPasskey(applePasskey(userHandle: Data(), key: key))
        #expect(empty.candidates.first?.passkeys.isEmpty == true)
        #expect(empty.omitted.map(\.reason) == [.passkeyUserHandleMissing])
    }

    /// The passkey an Apple Passwords import left out ("user handle longer than 64 bytes"), in the shapes seen: it is imported,
    /// stored, read back from disk by a second store, exported, and answers an assertion with the handle exactly as it arrived.
    @Test(arguments: [96, 512, WebsitePasskey.userHandleLimit])
    func aLongUserHandleSurvivesImportStoreReloadExportAndAssertion(length: Int) async throws {
        let handle = Data((0..<length).map { UInt8(truncatingIfNeeded: $0 &* 29 &+ 11) })
        let key = P256.Signing.PrivateKey()
        let incoming = data(credentials: [
            basicAuthentication(username: "ada", password: "pw"),
            applePasskey(userHandle: handle, key: key.derRepresentation),
        ])
        let preview = try CredentialExchangeCodec.preview(incoming, against: snapshot([]))
        #expect(preview.omitted.isEmpty)
        let accounts = try CredentialExchangeCodec.apply(preview, decisions: [])
        #expect(accounts.first?.passkeys.first?.userHandle == handle)

        try await VaultStoreFixture.with { f in
            try await f.withWallStore { store, access in
                let before = try await store.snapshot(vaultID: f.vaultID, using: access)
                _ = try await store.commit(vaultID: f.vaultID, accounts, expectedRevision: before.revision, cause: nil, using: access)
            }
            // A second store reads the vault from disk.
            try await f.withWallStore { store, access in
                let stored = try await store.snapshot(vaultID: f.vaultID, using: access)
                let account = try #require(stored.accounts.first)
                let passkey = try #require(account.passkeys.first)
                #expect(passkey.userHandle == handle && passkey.rpID == "paypal.com")

                let exported = try CredentialExchangeCodec.export(
                    stored,
                    selection: [.init(accountID: account.id, password: false, passkeyIDs: [passkey.id], totp: false)],
                    format: .v1
                )
                let exportedHandles = credentials(in: exported).compactMap { credential -> Data? in
                    guard case let .passkey(value) = credential else { return nil }
                    return value.userHandle
                }
                #expect(exportedHandles == [handle])
                let reread = try CredentialExchangeCodec.preview(exported, against: snapshot([]))
                #expect(reread.omitted.isEmpty && reread.candidates.first?.passkeys.first?.userHandle == handle)

                let challenge = Data("a long user handle".utf8)
                let request = WebAuthnRequest(
                    requestID: UUID(),
                    options: .assertion(WebAuthnAssertionOptions(
                        challenge: challenge, rpID: "paypal.com", allowCredentials: [passkey.credentialID], userVerification: .preferred
                    )),
                    deadline: ContinuousClock.now.advanced(by: .seconds(60))
                )
                let client = WebAuthnClientData(origin: "https://www.paypal.com", topOrigin: nil, crossOrigin: false, rpID: "paypal.com")
                let consent = WebAuthnConsent(requestID: request.requestID, userPresent: true, userVerified: false)
                let result = try WebsiteAuthenticator.makeAssertion(request, client: client, passkey: passkey, consent: consent)

                #expect(result.userHandle == handle)
                let page = try WebAuthnWire.resultJSON(result, operation: .get)
                let response = try #require(page["response"] as? [String: Any])
                #expect(response["userHandle"] as? String == WebAuthnWire.base64URL(handle))
                #expect(try WebAuthnWire.base64URLDecode(response["userHandle"], maximum: WebsitePasskey.userHandleLimit) == handle)
                _ = try WebAuthnVerifier.assertion(
                    authenticatorData: try #require(result.authenticatorData),
                    clientDataJSON: result.clientDataJSON,
                    signature: try #require(result.signature),
                    publicKey: WebAuthnVerifier.publicKey(x963: key.publicKey.x963Representation),
                    challenge: challenge,
                    origin: .init(origin: "https://www.paypal.com"),
                    rpID: "paypal.com",
                    userHandle: result.userHandle
                )
            }
            try f.verify()
        }
    }
}
